CREATE DATABASE IF NOT EXISTS cine_db
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;
USE cine_db;

SET NAMES utf8mb4;
SET CHARACTER SET utf8mb4;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS detalle_reserva;
DROP TABLE IF EXISTS reserva;
DROP TABLE IF EXISTS disponibilidad;
DROP TABLE IF EXISTS cliente;
DROP TABLE IF EXISTS pelicula;
DROP TABLE IF EXISTS genero;
DROP TABLE IF EXISTS estudio;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE estudio (
    codigo_estudio VARCHAR(10) PRIMARY KEY,
    nombre VARCHAR(100) NOT NULL,
    pais VARCHAR(60),
    activo BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE genero (
    codigo_genero VARCHAR(10) PRIMARY KEY,
    nombre VARCHAR(80) NOT NULL,
    descripcion VARCHAR(200)
);

CREATE TABLE pelicula (
    codigo_pelicula VARCHAR(15) PRIMARY KEY,
    titulo VARCHAR(150) NOT NULL,
    codigo_genero VARCHAR(10),
    codigo_estudio VARCHAR(10),
    duracion_minutos INT,
    clasificacion VARCHAR(10),
    formato VARCHAR(20),
    idioma VARCHAR(40),
    costo_proyeccion_referencia DECIMAL(10,2),
    tarifa_referencia_sala DECIMAL(10,2),
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT fk_pel_genero FOREIGN KEY (codigo_genero)
        REFERENCES genero(codigo_genero),
    CONSTRAINT fk_pel_estudio FOREIGN KEY (codigo_estudio)
        REFERENCES estudio(codigo_estudio)
);

CREATE TABLE cliente (
    codigo_cliente INT NOT NULL,
    cedula_ruc VARCHAR(25),
    apellido1 VARCHAR(40),
    apellido2 VARCHAR(40),
    nombres VARCHAR(70) NOT NULL,
    direccion VARCHAR(180),
    telefono_principal VARCHAR(20),
    telefono_alterno VARCHAR(20),
    email_contacto VARCHAR(120),
    fecha_alta DATETIME,
    tipo_cliente CHAR(1) NOT NULL DEFAULT 'N',
    permite_membresia CHAR(1) NOT NULL DEFAULT 'N',
    estado_registro CHAR(1) NOT NULL DEFAULT 'A',
    observaciones VARCHAR(250),
    PRIMARY KEY (codigo_cliente)
);

CREATE TABLE reserva (
    numero_reserva VARCHAR(15) PRIMARY KEY,
    fecha_hora DATETIME NOT NULL,
    sucursal_origen VARCHAR(60) NOT NULL,
    documento_cliente VARCHAR(25),
    canal_reserva VARCHAR(30),
    descuento DECIMAL(10,2) DEFAULT 0,
    estado VARCHAR(20) NOT NULL DEFAULT 'CONFIRMADA',
    observacion VARCHAR(200)
);

CREATE TABLE detalle_reserva (
    numero_reserva VARCHAR(15) NOT NULL,
    linea SMALLINT NOT NULL,
    codigo_pelicula VARCHAR(15),
    cantidad_asientos INT NOT NULL,
    tipo_asiento VARCHAR(20),
    PRIMARY KEY (numero_reserva, linea),
    CONSTRAINT fk_det_reserva FOREIGN KEY (numero_reserva)
        REFERENCES reserva(numero_reserva),
    CONSTRAINT fk_det_pelicula FOREIGN KEY (codigo_pelicula)
        REFERENCES pelicula(codigo_pelicula)
);

CREATE TABLE disponibilidad (
    sucursal_origen VARCHAR(60) NOT NULL,
    codigo_pelicula VARCHAR(15) NOT NULL,
    funciones_disponibles INT,
    funciones_minimas INT,
    fecha_ultima_funcion DATE,
    fecha_ultimo_movimiento DATE,
    PRIMARY KEY (sucursal_origen, codigo_pelicula),
    CONSTRAINT fk_disp_pelicula FOREIGN KEY (codigo_pelicula)
        REFERENCES pelicula(codigo_pelicula)
);

CREATE INDEX idx_reserva_fecha ON reserva(fecha_hora);
CREATE INDEX idx_reserva_sucursal ON reserva(sucursal_origen);
CREATE INDEX idx_reserva_cliente ON reserva(documento_cliente);
CREATE INDEX idx_det_pelicula ON detalle_reserva(codigo_pelicula);
CREATE INDEX idx_cliente_cedula_ruc ON cliente(cedula_ruc);


